def main():
 bpy.ops.wm.open_mainfile(filepath=str(SRC));bpy.context.scene.frame_set(1);cache=np.load(E.parent/'r0150-authored-rooted-locks/actual-current-scalp.npz');V=cache['world'];T=cache['triangles'];ids=cache['scalpVertexIds'];P=V[ids];n=49;t=np.linspace(0,1,n);rows=[];guides=[];rootIds=[];groups=[];groupRoots=[];lengths=[.91,.97,1.,.94,1.,.90,.98,.93,.99];scalpFaces=cache['scalpFaces'];scalpTree=BVHTree.FromPolygons([Vector(x) for x in V],T[scalpFaces].tolist(),all_triangles=True);rootTriangles=[];rootBary=[];rootFaces=[]
 for group,(name,seed,rest) in enumerate(PRIMARY):
  candidates=ids[P[:,0]<-.0005] if seed[0]<0 else ids[P[:,0]>.0005];ri=int(candidates[np.linalg.norm(V[candidates]-seed,axis=1).argmin()]);root=V[ri];knots=np.array([root,*rest]);dense=sampler.smooth_path(knots,197);groupRoots.append(root);curve=sampler.smooth_path(knots,n);tangent=np.gradient(curve,axis=0);tangent/=np.linalg.norm(tangent,axis=1)[:,None];side=np.cross(tangent,np.array([0.,1.,0.]));side/=np.maximum(np.linalg.norm(side,axis=1,keepdims=True),1e-9);depth=np.cross(tangent,side);width=np.interp(t,[0,.08,.25,.5,.7,.9,1],[0,.0018,.0038,.005,.004,.003,.0007]);thick=np.interp(t,[0,.08,.3,.6,.85,1],[0,.001,.0028,.0035,.0024,.0006]);indices=[]
  incident=T[scalpFaces][np.any(T[scalpFaces]==ri,axis=1)];normal=np.cross(V[incident[:,1]]-V[incident[:,0]],V[incident[:,2]]-V[incident[:,0]]).sum(0);normal/=np.linalg.norm(normal);tx=np.cross(normal,np.array([0.,1.,0.]));tx/=np.linalg.norm(tx);ty=np.cross(normal,tx)
  for k,(across,layer) in enumerate(( (x,y) for x in [-1,0,1] for y in [-1,0,1] )):
   target=root+tx*across*.0035+ty*layer*.004;hit,_,fi,_=scalpTree.find_nearest(Vector(target));rp=np.array(hit);face=int(scalpFaces[fi]);tri=T[face];aa,bb,cc=V[tri];v0=bb-aa;v1=cc-aa;v2=rp-aa;d00=v0@v0;d01=v0@v1;d11=v1@v1;d20=v2@v0;d21=v2@v1;den=d00*d11-d01*d01;bv=(d11*d20-d01*d21)/den;bw=(d00*d21-d01*d20)/den;bc=np.array([1-bv-bw,bv,bw]);assert bc.min()>-2e-5 and np.linalg.norm((V[tri]*bc[:,None]).sum(0)-rp)<2e-6;rj=int(tri[np.argmax(bc)]);at=t*lengths[k]*196;g=np.stack([np.interp(at,np.arange(197),dense[:,j]) for j in range(3)],axis=1);g+=(rp-root)[None,:]*(1-t[:,None])**1.5;g+=side*width[:,None]*across+depth*thick[:,None]*layer;g[0]=rp;guides.append(g);rootIds.append(rj);groups.append(group);indices.append(rj);rootTriangles.append(tri);rootBary.append(bc);rootFaces.append(face)
  rows.append({'group':group,'name':name,'actualRootVertex':ri,'actualRootWorld':root.tolist(),'originalPrimaryKnots':knots.tolist(),'secondaryActualRootVertices':indices,'secondaryLayers':3,'secondaryAcross':3,'secondaryEndFractions':lengths})
